-- NPDMS formal test empty-database release, state through V498.
-- MySQL 8.4 / Flyway 11.10.5. Use migrate, never baseline/repair/clean.
-- Excludes the 29 V310 pms legacy tables and their 87 read-only triggers.
-- Requires a selected EMPTY schema; existing installations use their original V migrations.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE npdms_release_empty_guard (
  allowed TINYINT NOT NULL,
  CONSTRAINT chk_npdms_release_requires_empty_database CHECK (allowed = 1)
);
INSERT INTO npdms_release_empty_guard
SELECT IF(DATABASE() IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM information_schema.tables
    WHERE table_schema=DATABASE() AND table_name <> 'flyway_schema_history')
  AND NOT EXISTS (SELECT 1 FROM information_schema.routines WHERE routine_schema=DATABASE())
  AND NOT EXISTS (SELECT 1 FROM information_schema.events WHERE event_schema=DATABASE()), 1, 0);
DROP TEMPORARY TABLE npdms_release_empty_guard;

