  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '验收名称',
  `acceptance_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PRELIMINARY' COMMENT '验收类型 PRELIMINARY 初验 / FINAL 终验',
  `acceptance_date` date DEFAULT NULL COMMENT '验收日期',
  `plan_id` bigint DEFAULT NULL COMMENT '关联交付计划编号',
  `applicant_user_id` bigint DEFAULT NULL COMMENT '申请人',
