  `source_version` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源版本',
  `current_direct_device_sn` varchar(100) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when ((`relationship_type` = _utf8mb4'DIRECT') and (`effective_to` is null) and (`deleted` = 0x00)) then `device_sn` else NULL end)) STORED,
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
