  CONSTRAINT `chk_contract_authority_status` CHECK ((`authority_status` in (_utf8mb4'PENDING_AUTHORITY',_utf8mb4'CONFIRMED'))),
  CONSTRAINT `chk_contract_dates` CHECK (((`expiry_date` is null) or (`effective_date` is null) or (`expiry_date` >= `effective_date`))),
