  `device_type_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备类型名称快照',
  `sn` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备序列号（旧序列号快照，新行不写入）',
