  `product_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '换货产品编码（快照）',
  `product_model` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '换货产品型号（快照）',
