  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `active_ref` varchar(64) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (if((`deleted` = 0x00),(case when (`scope_detail_id` is not null) then concat(_utf8mb4'D',`scope_detail_id`) when (`scope_id` is not null) then concat(_utf8mb4'S',`scope_id`) when (`device_id` is not null) then concat(_utf8mb4'V',`device_id`) end),NULL)) STORED COMMENT '当前生效清单行引用键',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_exchange_active_ref` (`tenant_id`,`exchange_id`,`active_ref`),
  KEY `idx_exchange_serial` (`tenant_id`,`exchange_id`,`deleted`)
