  `project_id` bigint NOT NULL COMMENT '关联项目ID',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险名称',
  `risk_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SINGLE_DEVICE' COMMENT '风险类型：SINGLE_DEVICE单机/SCENARIO场景',
  `device_id` bigint DEFAULT NULL COMMENT '关联设备ID',
  `device_serial` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备序列号',
  `device_model` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备型号',
  `scenario` text COLLATE utf8mb4_unicode_ci COMMENT '风险场景描述',
  `risk_level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '风险等级：HIGH高/MEDIUM中/LOW低',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿/1已识别/2已确认/3已同步CRM/4已关闭',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
