CREATE TABLE `kno_announcement` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告编号（如 TA-2026-001）',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告标题',
  `announcement_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TECH_NOTICE' COMMENT '公告类型：TECH_NOTICE技术公告/EOS停产/EOM停维',
  `product_model` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '适用设备型号',
  `affected_versions` text COLLATE utf8mb4_unicode_ci COMMENT '影响版本范围JSON数组',
  `publish_date` date DEFAULT NULL COMMENT '发布日期',
  `effective_date` date DEFAULT NULL COMMENT '生效日期',
  `expire_date` date DEFAULT NULL COMMENT '失效日期',
  `severity` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '严重等级：CRITICAL/HIGH/MEDIUM/LOW',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '公告内容富文本',
  `handling_suggestion` text COLLATE utf8mb4_unicode_ci COMMENT '处置建议',
  `file_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件URL',
  `file_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件名',
  `file_size` bigint DEFAULT NULL COMMENT '附件大小（字节）',
  `file_checksum` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件校验值',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿/1已发布/2已停用',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `creator_user_id` bigint DEFAULT NULL COMMENT '创建人',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pms_eng_announcement_code` (`code`,`tenant_id`),
  KEY `idx_pms_eng_announcement_type` (`announcement_type`),
  KEY `idx_pms_eng_announcement_model` (`product_model`),
  KEY `idx_pms_eng_announcement_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='技术公告与停产停维';
