CREATE TABLE `plt_delivery_material` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `owner_module` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源实体所属模块',
  `entity_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源实体类型',
