  `type_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '材料类型编码',
  `material_kind` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'FILE' COMMENT '材料证据锚 FILE=文件版本 / BUSINESS_RESULT=业务成果',
  `requirement_id` bigint DEFAULT NULL COMMENT '绑定的模板冻结要求（模板行材料直连要求）',
  `project_id` bigint DEFAULT NULL COMMENT '项目上下文（供项目级汇总）',
  `business_object_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务成果对象类型（BUSINESS_RESULT 行，统一目录 entityType）',
  `business_object_id` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务成果对象ID（type|objectId|resultId|formedAt 复合身份）',
  `business_revision_no` bigint DEFAULT NULL COMMENT '业务成果修订锚（如方案基线版本；无修订对象为 NULL）',
  `file_reference_id` bigint DEFAULT NULL COMMENT '统一文件引用ID（BUSINESS_RESULT 行为空）',
  `file_artifact_id` bigint DEFAULT NULL COMMENT '文件工件ID（BUSINESS_RESULT 行为空）',
  `file_version_no` int DEFAULT NULL COMMENT '文件版本号（BUSINESS_RESULT 行为空）',
  `file_sha256` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件内容摘要（BUSINESS_RESULT 行为空）',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名称（BUSINESS_RESULT 行为空）',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料标题',
  `source_kind` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UPLOAD' COMMENT '来源 UPLOAD/GENERATED/ASSOCIATED',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '状态 ACTIVE/WITHDRAWN',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '逻辑删除',
  `archive_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_REQUIRED' COMMENT '归档补偿状态 NOT_REQUIRED/PENDING_COMPENSATION/ARCHIVED/INVALID',
  `archive_failure_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '归档失败原因编码',
  `archive_retry_count` int NOT NULL DEFAULT '0' COMMENT '归档补偿重试次数',
  `archive_time` datetime(3) DEFAULT NULL COMMENT '归档完成时间',
  `source_identity_key` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新登记来源版本身份SHA256（旧行保持NULL）',
  `business_type_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '稳定业务类型/来源目录编码，不是模板要求编码',
  `source_owner_module` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_entity_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_entity_id` bigint DEFAULT NULL,
  `source_revision_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plt_delivery_mat` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`type_code`,`file_artifact_id`,`file_version_no`),
  UNIQUE KEY `uk_plt_delivery_material_source` (`tenant_id`,`source_identity_key`),
  KEY `idx_plt_delivery_mat_entity` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`type_code`),
  KEY `idx_plt_delivery_mat_project` (`tenant_id`,`project_id`),
  KEY `idx_plt_delivery_mat_requirement` (`requirement_id`),
  KEY `idx_plt_delivery_mat_business` (`tenant_id`,`owner_module`,`entity_type`,`entity_id`,`business_object_type`,`business_object_id`),
  KEY `idx_plt_delivery_mat_archive` (`tenant_id`,`archive_status`),
  KEY `idx_plt_delivery_native_source` (`tenant_id`,`source_owner_module`,`source_entity_type`,`source_entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='交付-实际材料记录';
