  `result_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_context` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_object_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
