  `target_sequence` int DEFAULT NULL COMMENT '目标顺序',
  `result_key` varchar(96) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`result_type` = _utf8mb4'RETAINED') then _utf8mb4'RETAINED' else concat(`target_role`,_utf8mb4':',`target_sequence`) end)) STORED,
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `create_time` datetime(3) NOT NULL COMMENT '创建时间',
