  `version` bigint NOT NULL DEFAULT '0' COMMENT '行版本（乐观锁）',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `stage_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参与计划的阶段编码',
  `signing_method` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签约方式（字典 pms_signing_method）；空=全部签约方式',
  `source_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '建议来源：PMS_IMPORTED 带入自身计划验收时间 / DURATION_REQUIRE 锚工期要求 / STAGE_PLAN 参照阶段',
  `reference_stage_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参照阶段编码（STAGE_PLAN 时必填，须晚于自身阶段）',
  `offset_months` int NOT NULL DEFAULT '0' COMMENT '参照时间偏移月数（负=提前）',
  `offset_days` int NOT NULL DEFAULT '0' COMMENT '参照时间偏移天数（负=提前，如 -14=2周）',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注（需求原文与映射说明）',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_stage_variant` (`tenant_id`,`stage_code`,`signing_method`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='3.1 工期建议计划时间规则（Demo 页面9 / Excel 3.1；建议最迟完成 = 参照时间 - 偏移）';
