  `tenant_id` bigint NOT NULL,
  `project_id` bigint NOT NULL,
  `task_id` bigint DEFAULT NULL,
  `execution_contract_id` bigint NOT NULL,
  `contract_version` int NOT NULL,
  `owner_context` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `object_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `object_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `fact_version` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL,
  `linked_by` bigint NOT NULL,
  `linked_at` datetime(6) NOT NULL,
  `unlinked_by` bigint DEFAULT NULL,
  `unlinked_at` datetime(6) DEFAULT NULL,
  `active_marker` tinyint GENERATED ALWAYS AS (if((`unlinked_at` is null),1,NULL)) STORED,
  `version` int NOT NULL DEFAULT '0',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `update_time` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
