  `customer_evidence_scope_version` bigint DEFAULT NULL COMMENT '冻结业务对象授权范围版本',
  `process_definition_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '冻结BPM流程定义键',
