CREATE TABLE `sol_preparation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '准备业务版本ID',
  `project_id` bigint NOT NULL COMMENT 'PROJ项目ID',
  `preparation_type_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '准备类型，V1固定PRE_02_SITE_SURVEY',
  `business_version` int unsigned NOT NULL COMMENT '项目内准备业务版本',
  `current_marker` tinyint DEFAULT NULL COMMENT '当前版本标记：当前=1，历史=NULL',
  `source_preparation_id` bigint DEFAULT NULL COMMENT 'PRE-04修订来源完成版ID',
  `dynamic_form_instance_id` bigint DEFAULT NULL COMMENT 'PLATFORM动态表单实例逻辑ID',
  `draft_marker` tinyint DEFAULT NULL COMMENT 'PRE-04当前草稿标记：当前=1，其余=NULL',
  `effective_marker` tinyint DEFAULT NULL COMMENT 'PRE-04当前有效完成版标记：当前=1，其余=NULL',
  `template_id` bigint NOT NULL COMMENT '冻结项目模板ID',
  `template_revision_id` bigint NOT NULL COMMENT '冻结项目模板修订ID',
  `template_snapshot` json NOT NULL COMMENT '冻结PRE-02模板及WorkBinding事实',
  `fixed_form_catalog_version` int unsigned NOT NULL COMMENT '固定表单目录版本',
  `status_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '准备生命周期状态',
  `readiness_status_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '当前实施就绪状态',
  `latest_readiness_snapshot_id` bigint DEFAULT NULL COMMENT '最新不可变就绪快照ID',
  `input_version` int unsigned NOT NULL DEFAULT '0' COMMENT '就绪输入版本',
  `readiness_version` int unsigned NOT NULL DEFAULT '0' COMMENT '就绪事实版本',
  `snapshot_current` bit(1) NOT NULL DEFAULT b'0' COMMENT '最新快照是否仍对应当前输入',
  `content_version` int unsigned DEFAULT NULL COMMENT 'PRE-04正文与附件事实版本',
  `completed_by` bigint DEFAULT NULL COMMENT 'PRE-04完成人',
  `completed_at` datetime(3) DEFAULT NULL COMMENT 'PRE-04完成时间',
  `submitted_at` datetime(3) DEFAULT NULL COMMENT '提交确认时间',
  `confirmed_at` datetime(3) DEFAULT NULL COMMENT '全部确认时间',
  `returned_at` datetime(3) DEFAULT NULL COMMENT '退回时间',
  `return_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '退回原因',
  `version` int unsigned NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `entity_value_json` json DEFAULT NULL COMMENT 'PRE-04 entity-owned ordinary values',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sol_preparation_business_version` (`tenant_id`,`project_id`,`preparation_type_code`,`business_version`),
  UNIQUE KEY `uk_sol_preparation_tenant_row` (`tenant_id`,`id`),
  UNIQUE KEY `uk_sol_preparation_current` (`tenant_id`,`project_id`,`preparation_type_code`,`current_marker`),
  UNIQUE KEY `uk_sol_preparation_draft` (`tenant_id`,`project_id`,`preparation_type_code`,`draft_marker`),
  UNIQUE KEY `uk_sol_preparation_effective` (`tenant_id`,`project_id`,`preparation_type_code`,`effective_marker`),
  UNIQUE KEY `uk_sol_preparation_dynamic_form_instance` (`tenant_id`,`dynamic_form_instance_id`),
  KEY `idx_sol_preparation_project_status` (`tenant_id`,`project_id`,`status_code`,`business_version`),
  KEY `fk_sol_preparation_latest_snapshot` (`tenant_id`,`latest_readiness_snapshot_id`),
  KEY `idx_sol_preparation_source` (`tenant_id`,`source_preparation_id`),
  CONSTRAINT `fk_sol_preparation_latest_snapshot` FOREIGN KEY (`tenant_id`, `latest_readiness_snapshot_id`) REFERENCES `sol_preparation_readiness_snapshot` (`tenant_id`, `id`),
  CONSTRAINT `fk_sol_preparation_source` FOREIGN KEY (`tenant_id`, `source_preparation_id`) REFERENCES `sol_preparation` (`tenant_id`, `id`),
  CONSTRAINT `chk_sol_preparation_business_version` CHECK (((`business_version` > 0) and (`fixed_form_catalog_version` > 0))),
  CONSTRAINT `chk_sol_preparation_current_marker` CHECK (((`current_marker` is null) or (`current_marker` = 1))),
  CONSTRAINT `chk_sol_preparation_pre04_marker_values` CHECK ((((`draft_marker` is null) or (`draft_marker` = 1)) and ((`effective_marker` is null) or (`effective_marker` = 1)))),
  CONSTRAINT `chk_sol_preparation_pre04_markers` CHECK ((((`preparation_type_code` = _utf8mb4'PRE_02_SITE_SURVEY') and (`dynamic_form_instance_id` is null) and (`draft_marker` is null) and (`effective_marker` is null) and (`source_preparation_id` is null) and (`content_version` is null) and (`completed_by` is null) and (`completed_at` is null)) or ((`preparation_type_code` = _utf8mb4'PRE_04_REQUIREMENT_ANALYSIS') and (`dynamic_form_instance_id` is not null) and (`current_marker` is null) and (`content_version` is not null) and (((`status_code` = _utf8mb4'DRAFT') and (`draft_marker` = 1) and (`effective_marker` is null) and (`completed_by` is null) and (`completed_at` is null)) or ((`status_code` = _utf8mb4'COMPLETED') and (`draft_marker` is null) and ((`effective_marker` is null) or (`effective_marker` = 1)) and (`completed_by` is not null) and (`completed_at` is not null)))))),
  CONSTRAINT `chk_sol_preparation_readiness_status` CHECK ((`readiness_status_code` in (_utf8mb4'NOT_READY',_utf8mb4'READY'))),
  CONSTRAINT `chk_sol_preparation_status` CHECK ((((`preparation_type_code` = _utf8mb4'PRE_02_SITE_SURVEY') and (`status_code` in (_utf8mb4'DRAFT',_utf8mb4'PENDING_CONFIRMATION',_utf8mb4'CONFIRMED',_utf8mb4'RETURNED'))) or ((`preparation_type_code` = _utf8mb4'PRE_04_REQUIREMENT_ANALYSIS') and (`status_code` in (_utf8mb4'DRAFT',_utf8mb4'COMPLETED'))))),
  CONSTRAINT `chk_sol_preparation_type` CHECK ((`preparation_type_code` in (_utf8mb4'PRE_02_SITE_SURVEY',_utf8mb4'PRE_04_REQUIREMENT_ANALYSIS')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SOL PRE-02准备聚合与当前就绪指针';
