INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442159,970000000000442001,'DUAL_SILENT_DUAL_R029_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','心跳接口ip是否为私网ip','心跳接口ip一定要配置私网ip（10.0.0.0/8，172.16.0.0/16，192.168.0.0/24，且不允许与现网地址冲突），尽量不要配置公网ip，否则在开启地域访问控制策略场景可能会影响会话及配置同步功能。\n来源：0807设计表，3.2双机部署规范性检查表，第29行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 29, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "心跳接口ip是否为私网ip"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',580,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
