INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442163,970000000000442001,'DUAL_SILENT_DUAL_R033_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','静默双机状态是否符合预期','双机状态是否符合预期，状态维持时间是否符合预期\n来源：0807设计表，3.2双机部署规范性检查表，第33行。原复合检查拆为独立作答项，保留原项名及说明。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 33, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": true, "originalName": "静默双机状态检查"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',620,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442164,970000000000442001,'DUAL_SILENT_DUAL_R033_2',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','静默双机状态维持时间是否符合预期','双机状态是否符合预期，状态维持时间是否符合预期\n来源：0807设计表，3.2双机部署规范性检查表，第33行。原复合检查拆为独立作答项，保留原项名及说明。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 33, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 2, "sheet": "3.2双机部署规范性检查表", "split": true, "originalName": "静默双机状态检查"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',630,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442165,970000000000442001,'DUAL_SILENT_DUAL_R034_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否所有业务接口都配置静默接口（不包含管理口、心跳口、配置同步接口）','1、备机需要将静默接口列表中的接口静默，否则会出现IP地址冲突以及流量继续转发至备机的情况，特别是新扩容的接口，容易出现遗漏的情况。\n2、静默接口中不能配置管理口、心跳口以及配置同步接口，否则会导致备机无法管理、双机状态异常、配置同步异常等情况\n来源：0807设计表，3.2双机部署规范性检查表，第34行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 34, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否所有业务接口都配置静默接口（不包含管理口、心跳口、配置同步接口）"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',640,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442166,970000000000442001,'DUAL_SILENT_DUAL_R035_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否所有业务接口都配置监听接口（包含聚合接口）','要求所有业务接口都配置监听接口，包含bond口，防止bond口down物理口up情况下双机无法切换而影响业务\n来源：0807设计表，3.2双机部署规范性检查表，第35行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 35, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否所有业务接口都配置监听接口（包含聚合接口）"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',650,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442167,970000000000442001,'DUAL_SILENT_DUAL_R036_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','备机静默接口是否处于slient静默状态','开发者试图执行 dev_cfg mac 接口 st 命令查看接口静默状态为slient\n来源：0807设计表，3.2双机部署规范性检查表，第36行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 36, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "备机静默接口是否处于slient静默状态"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',660,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442168,970000000000442001,'DUAL_SILENT_DUAL_R037_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','主备机管理协议http/https/telnet/ssh开启状态是否一致','配置同步使用的是http/https/telnet/ssh协议，必须保证静默双机两端设备http/https/telnet/ssh配置一致\n来源：0807设计表，3.2双机部署规范性检查表，第37行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 37, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "主备机管理协议http/https/telnet/ssh开启状态是否一致"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',670,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442169,970000000000442001,'DUAL_SILENT_DUAL_R038_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','配置同步功能检查','检查主备配置同步禁用开关是否关闭，默认开关关闭，此情况下配置同步才可正常。（功能位于 高可靠性--双机热备--配置同步参数 模块高级配置）\n来源：0807设计表，3.2双机部署规范性检查表，第38行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 38, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "配置同步功能检查"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',680,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442170,970000000000442001,'DUAL_SILENT_DUAL_R039_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','主备机会话同步功能是否均开启','主备机会话同步配置必须一致。若会话同步未开启，则主备切换会导致部分长连接业务持续异常，此情况下需让客户手动重新拉起业务。\n来源：0807设计表，3.2双机部署规范性检查表，第39行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 39, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "主备机会话同步功能是否均开启"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',690,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442171,970000000000442001,'DUAL_SILENT_DUAL_R040_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否开启双机回切延时（ hotbackup shrp delay time xxx）','主备回切若配置延时，则回切会按照配置的时间延时后再回切，在部分场景下不能配置该功能，例如割接过程中出现问题快速回退，如果配置了该功能，就无法迅速回切来达到恢复业务的目的（可以通过直接修改初始优先级来实现主备迅速回切）备注：神七D035开局版本及之后版本都支持\n来源：0807设计表，3.2双机部署规范性检查表，第40行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 40, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否开启双机回切延时（ hotbackup shrp delay time xxx）"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',700,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442172,970000000000442001,'DUAL_SILENT_DUAL_R041_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置接口延迟up','主要用于框式设备，以防备机在重启过程中因业务板未重启完成的情况接口短暂up影响业务。页面高可靠性--接口延迟配置查看是否有配置，或者命令行show run | in linkup-delay查看是否存在接口延迟up配置，然后再确定是哪些接口有此配置\n来源：0807设计表，3.2双机部署规范性检查表，第41行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 41, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否有配置接口延迟up"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',710,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442173,970000000000442001,'DUAL_SILENT_DUAL_R042_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置静默双机监听业务板cpu（hotbackup shrp monitor-board slot x priority n）','主要用于框式设备，防止在单业务板场景下，主设备业务板重启，主备状态未切换而影响业务。备注：神七D035开局版本及之后版本都支持\n来源：0807设计表，3.2双机部署规范性检查表，第42行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 42, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否有配置静默双机监听业务板cpu（hotbackup shrp monitor-board slot x priority n）"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',720,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442174,970000000000442001,'DUAL_SILENT_DUAL_R043_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查是否需要配置Track ip','设备静默双机环境，上下行对接二层交换机或透明部署设备，仅通过接口 UP/DOWN 状态无法判断业务实际连通性，需配置 Track IP。Track ip联动静默双机必须在双机初始优先级一样的场景下使用，优先级不一致会导致Track ip联动切换失效。\nFW 整机纯透明、上下行直连三层设备：链路断裂、对端设备断电、接口Down会直接造成防火墙接口 Down，依靠静默双机接口监控就能正常切主备，无需配置 Track IP。\n备注：神六D198官网及之后版本支持\n神七所有版本均支持\n来源：0807设计表，3.2双机部署规范性检查表，第43行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 43, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "检查是否需要配置Track ip"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',730,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442175,970000000000442001,'DUAL_SILENT_DUAL_R044_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查IP是否可以配置为Track ip','探测 IP 需保证主、备两台防火墙路由均可正常可达、网络稳定性高，优先沿着业务转发路径选取。1）首选：对端三层互联的 IP地址；2）备选：其他内网核心网关/固定业务服务器IP。\nTrack IP 禁止选用：1）仅主防火墙可达、备防火墙路由不通的IP；2）频繁离线、在线状态波动较大的终端IP。\n备注：神六D198官网及之后版本支持\n神七所有版本均支持\n来源：0807设计表，3.2双机部署规范性检查表，第44行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 44, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "检查IP是否可以配置为Track ip"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',740,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442176,970000000000442001,'DUAL_SILENT_DUAL_R045_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否配置有trackip\n（trackip name xxxx icmp track-address x.x.x.x output-interface  vlan-if20(出接口) next-hop x.x.x.x src-ip x.x.x.x）','用于链路健康检查，对链路状态进行监听。此配置会双机同步，output-interface（出接口）、next-hop（下一条）属于可选参数，可不配置。\n备注：神六D198官网及之后版本支持\n神七所有版本均支持\n来源：0807设计表，3.2双机部署规范性检查表，第45行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 45, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否配置有trackip\\n（trackip name xxxx icmp track-address x.x.x.x output-interface  vlan-if20(出接口) next-hop x.x.x.x src-ip x.x.x.x）"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',750,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442177,970000000000442001,'DUAL_SILENT_DUAL_R046_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置静默双机监听trackip\n（hotbackup shrp trackip xxxx）','引用链路健康检查，达到在主机接口状态UP，但是网络不通的情况下进行双机切换，快速恢复业务的目的，此配置不能同步，每一台设备都需要手动配置调用Track ip策略。\n备注：神六D198官网及之后版本支持\n神七所有版本均支持\n来源：0807设计表，3.2双机部署规范性检查表，第46行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 46, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否有配置静默双机监听trackip\\n（hotbackup shrp trackip xxxx）"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',760,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442178,970000000000442001,'DUAL_SILENT_DUAL_R047_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查上下游设备是否有配置静态ARP/ND、MAC/IP绑定','如果上下游设备配置静态ARP/ND或MAC/IP绑定功能，主备机切换后会导致业务不通（部分组网中会开启主备机接口的MAC地址同步，同样也需要检查上下游设备静态ARP/ND或MAC/IP绑定是否有绑定接口）\n来源：0807设计表，3.2双机部署规范性检查表，第47行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 47, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "检查上下游设备是否有配置静态ARP/ND、MAC/IP绑定"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',770,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442179,970000000000442001,'DUAL_SILENT_DUAL_R048_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','检查上下游设备是否有开启学习免费ARP','部分厂商默认不开启免费ARP学习或者关闭了免费ARP学习功能，会导致备机切为主机后需要等ARP老化后重新学习流量才能通，影响双机的收敛时间\n来源：0807设计表，3.2双机部署规范性检查表，第48行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 48, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "检查上下游设备是否有开启学习免费ARP"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'SILENT_DUAL','ENABLED',780,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442180,970000000000442001,'DUAL_DRP_DUAL_R056_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口之间是否存在网络设备','心跳口优选直连，非直连请提前咨询总部确认\n来源：0807设计表，3.2双机部署规范性检查表，第56行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 56, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP心跳口之间是否存在网络设备"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',790,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442181,970000000000442001,'DUAL_DRP_DUAL_R057_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口光模块收发光检查','若存在成员口光模块收发光异常，需要及时更换光模块\n来源：0807设计表，3.2双机部署规范性检查表，第57行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 57, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP心跳口光模块收发光检查"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',800,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442182,970000000000442001,'DUAL_DRP_DUAL_R058_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口接口计数统计检查','命令：dev_cfg eth sw show all查看，对应心跳物理口如果存在crc丢包、rxdrop丢包或txdrop丢包持续增长。错包多会影响心跳状态及同步配置情况。\n来源：0807设计表，3.2双机部署规范性检查表，第58行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 58, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP心跳口接口计数统计检查"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',810,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442183,970000000000442001,'DUAL_DRP_DUAL_R059_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口ip是否为私网ip','心跳接口ip一定要配置私网ip（10.0.0.0/8，172.16.0.0/16，192.168.0.0/24，且不允许与现网地址冲突），尽量不要配置公网ip，否则在开启地域访问控制策略场景可能会影响会话及配置同步功能。\n来源：0807设计表，3.2双机部署规范性检查表，第59行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 59, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP心跳口ip是否为私网ip"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',820,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442184,970000000000442001,'DUAL_DRP_DUAL_R060_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口作为配置同步接口时是否配置接口服务限制','心跳口作为配置同步接口时禁止配置接口服务限制\n来源：0807设计表，3.2双机部署规范性检查表，第60行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 60, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP心跳口作为配置同步接口时是否配置接口服务限制"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',830,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442185,970000000000442001,'DUAL_DRP_DUAL_R061_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口互ping是否通','1：DRP状态维护为组播报文，如果DRP心跳口ping不通，则DRP状态异常。2：如果DRP心跳口ping不通，当心跳口作为配置同步接口时会存在配置同步异常情况。\n来源：0807设计表，3.2双机部署规范性检查表，第61行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 61, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP心跳口互ping是否通"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',840,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442186,970000000000442001,'DUAL_DRP_DUAL_R062_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP心跳口聚合口配置是否一致','优先静态聚合，检查心跳口bond聚合本端和对端是否一致\n来源：0807设计表，3.2双机部署规范性检查表，第62行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 62, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP心跳口聚合口配置是否一致"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',850,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442187,970000000000442001,'DUAL_DRP_DUAL_R063_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP主备状态检查','双机状态是否符合预期。\n来源：0807设计表，3.2双机部署规范性检查表，第63行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 63, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP主备状态检查"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',860,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442188,970000000000442001,'DUAL_DRP_DUAL_R064_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','双机动态路由cost值是否正常','1：查看设备发布出去的ospf路由cost值是否符合设备状态，通过show ip ospf database self-originate 命令查看本设备adv-router,下一步通过命令show ip ospf （进程号）database external adv-router XXX.XXX.XXX.XXX（本设备路由器id值）  查看该adv-router的 metric值来判断是否符合预期。\n2:查看设备发布出去的bgp路由cost值是否符合设备状态，通过show ip bgp ipv4 unicast 查看metric值来判断是否符合预期。\n来源：0807设计表，3.2双机部署规范性检查表，第64行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 64, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "双机动态路由cost值是否正常"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',870,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442189,970000000000442001,'DUAL_DRP_DUAL_R065_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','配置同步功能检查','检查主备配置同步禁用开关是否关闭，默认开关关闭，此情况下配置同步才可正常。（功能位于 高可靠性--普通双机-禁用所有配置同步模块）\n来源：0807设计表，3.2双机部署规范性检查表，第65行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 65, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "配置同步功能检查"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',880,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442190,970000000000442001,'DUAL_DRP_DUAL_R066_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否开启drp抢占延迟，drp preempt delay X','drp延迟抢占配置180S，应用场景：当主设备（fw1）重启后，备（fw2）接替了主，在旧主（fw1）重启完成后保证fw1的所有表项准备完成后再接替主的状态，随后再引流量到设备处理。\n来源：0807设计表，3.2双机部署规范性检查表，第66行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 66, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否开启drp抢占延迟，drp preempt delay X"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',890,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442191,970000000000442001,'DUAL_DRP_DUAL_R067_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','interface 接口（tengigeX_X） linkup-delay 180','业务接口延迟UP配置180S，所有业务口都需要配置，保证设备重启时OSPF进程先于DRP进程启动后，OSPF先切为主。\n来源：0807设计表，3.2双机部署规范性检查表，第67行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 67, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "interface 接口（tengigeX_X） linkup-delay 180"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',900,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442192,970000000000442001,'DUAL_DRP_DUAL_R068_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置drp监听业务板drp track board slotX reduced 10','主要用于框式设备，防止在单业务板场景下，主设备业务板重启，主备状态未切换而影响业务。业务板卡要监听所有的。每个业务板推荐值是10，按实际情况调整。假设该设备业务板坏了，导致设备状态切换，此时业务流量将不会走这台设备。\n来源：0807设计表，3.2双机部署规范性检查表，第68行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 68, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否有配置drp监听业务板drp track board slotX reduced 10"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',910,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442193,970000000000442001,'DUAL_DRP_DUAL_R069_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','是否有配置监听接口drp track interface 接口 reduced 10','用于所有设备，防止在接口出现异常时未及时切换状态，导致影响业务。通常配置：监听上下行所有业务接口。推荐配置每个接口优先级为10,假设一台设备接口down了，导致设备状态切换到备的话，此时业务流量不会走这台设备。\n来源：0807设计表，3.2双机部署规范性检查表，第69行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 69, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "是否有配置监听接口drp track interface 接口 reduced 10"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',920,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442194,970000000000442001,'DUAL_DRP_DUAL_R070_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','drp虚拟ip配置一致性','drp虚拟ip配置保持一致。否则会出现主备协商异常的风险。\n来源：0807设计表，3.2双机部署规范性检查表，第70行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 70, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "drp虚拟ip配置一致性"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',930,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442195,970000000000442001,'DUAL_DRP_DUAL_R071_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP监听接口优先级是否符合设计','根据现网设计需求配置主备优先级差异，满足客户主备切换需求。监听接口(板卡)/监听IP/BFD，优先级默认值 10（1-255)。\n来源：0807设计表，3.2双机部署规范性检查表，第71行。原复合检查拆为独立作答项，保留原项名及说明。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 71, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": true, "originalName": "优先级确认：确认优先级配置是否符合设计，监听接口/监听IP/BFD"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',940,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
