INSERT INTO `cut_cutover_checklist_item_definition_revision` (`id`,`configuration_revision_id`,`stable_item_key`,`item_definition_version`,`item_type_code`,`business_category_code`,`item_name`,`item_description`,`interface_format_code`,`interface_schema`,`feedback_format_code`,`required_flag`,`work_mode_code`,`external_source_config`,`subtable_code`,`status_code`,`sort_order`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`,`external_interface_code`,`external_manual_fallback_flag`) VALUES (970000000000442200,970000000000442001,'DUAL_DRP_DUAL_R074_1',1,'DUAL_MACHINE_CHECK','DUAL_DEPLOYMENT_CHECK','DRP是否开启会话同步','show session-sync configuration查看会话同步是否正常。\n来源：0807设计表，3.2双机部署规范性检查表，第74行。','TABLE','{"fields": [{"code": "executed", "type": "BOOLEAN", "label": "是否已核查", "required": true}, {"code": "normal", "type": "BOOLEAN", "label": "是否符合本次部署要求", "required": true}, {"code": "remark", "type": "TEXT", "label": "事实说明及特殊情况备注", "required": true, "visibleWhen": {"field": "normal", "equals": false}}], "source": {"row": 74, "file": "4、割接平台设计-数据整理（0807).xlsx", "part": 1, "sheet": "3.2双机部署规范性检查表", "split": false, "originalName": "DRP是否开启会话同步"}}','BOOLEAN_REMARK',1,'DIRECT',NULL,'DRP_DUAL','ENABLED',990,0,'cut-special-20261012','2026-10-17 17:41:21.000000','cut-special-20261012','2026-10-17 17:41:21.000000',0,1,NULL,NULL);
